create table if not exists public.payment_exceptions (id bigint generated by default as identity primary key,order_id bigint not null references public.orders(id) on delete cascade,user_id uuid not null,exception_type text not null,source text not null,payment_id text,order_status text,details jsonb not null default '{}'::jsonb,status text not null default 'open',occurrence_count integer not null default 1,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),resolved_at timestamptz,resolution_note text,constraint payment_exceptions_type_check check (exception_type in ('inactive_order_capture','different_payment_reference')),constraint payment_exceptions_source_check check (source in ('authenticated_reconcile','razorpay_webhook','verify_payment')),constraint payment_exceptions_status_check check (status in ('open','resolved')),constraint payment_exceptions_occurrence_check check (occurrence_count > 0),constraint payment_exceptions_resolution_check check ((status='open' and resolved_at is null) or (status='resolved' and resolved_at is not null))); create unique index if not exists payment_exceptions_open_identity_key on public.payment_exceptions(order_id,exception_type,coalesce(payment_id,'')) where status='open'; create index if not exists payment_exceptions_open_last_seen_idx on public.payment_exceptions(status,last_seen_at desc); alter table public.payment_exceptions enable row level security; revoke all on table public.payment_exceptions from public,anon,authenticated; grant select,insert,update on table public.payment_exceptions to service_role; create or replace function public.record_payment_exception(p_order_id bigint,p_user_id uuid,p_exception_type text,p_source text,p_payment_id text default null,p_order_status text default null,p_details jsonb default '{}'::jsonb) returns public.payment_exceptions language plpgsql security definer set search_path to 'pg_catalog','public' as $function$ declare e public.payment_exceptions%rowtype; v_payment_id text:=nullif(trim(coalesce(p_payment_id,'')),''); begin if current_user not in ('service_role','postgres') then raise exception 'service role required'; end if; if p_exception_type not in ('inactive_order_capture','different_payment_reference') then raise exception 'Unsupported payment exception type'; end if; if p_source not in ('authenticated_reconcile','razorpay_webhook','verify_payment') then raise exception 'Unsupported payment exception source'; end if; perform 1 from public.orders where id=p_order_id and user_id=p_user_id; if not found then raise exception 'Order not found'; end if; update public.payment_exceptions set source=p_source,order_status=nullif(trim(coalesce(p_order_status,'')),''),details=details||coalesce(p_details,'{}'::jsonb),occurrence_count=occurrence_count+1,last_seen_at=now() where order_id=p_order_id and exception_type=p_exception_type and coalesce(payment_id,'')=coalesce(v_payment_id,'') and status='open' returning * into e; if found then return e; end if; begin insert into public.payment_exceptions(order_id,user_id,exception_type,source,payment_id,order_status,details) values(p_order_id,p_user_id,p_exception_type,p_source,v_payment_id,nullif(trim(coalesce(p_order_status,'')),''),coalesce(p_details,'{}'::jsonb)) returning * into e; return e; exception when unique_violation then update public.payment_exceptions set source=p_source,order_status=nullif(trim(coalesce(p_order_status,'')),''),details=details||coalesce(p_details,'{}'::jsonb),occurrence_count=occurrence_count+1,last_seen_at=now() where order_id=p_order_id and exception_type=p_exception_type and coalesce(payment_id,'')=coalesce(v_payment_id,'') and status='open' returning * into e; if not found then raise; end if; return e; end; end; $function$; revoke all on function public.record_payment_exception(bigint,uuid,text,text,text,text,jsonb) from public,anon,authenticated; grant execute on function public.record_payment_exception(bigint,uuid,text,text,text,text,jsonb) to service_role;